CustomField.formula:
MAX(0,

if( DateValue(Dynamic_Time_Start_Date_Time__c) = DateValue(Now()),

    (
        if(Dynamic_Time_End_Hour__c<8, 8, if(Dynamic_Time_End_Hour__c>20, 20, Dynamic_Time_End_Hour__c))
        +
        if(Dynamic_Time_End_Hour__c<8 || Dynamic_Time_End_Hour__c>=20, 0, Minute(TimeValue(Now()))/60)
    )
    -
    (
        if(Dynamic_CreatedHour__c<8, 8, if(Dynamic_CreatedHour__c>20, 20, Dynamic_CreatedHour__c))
        +
        if(Dynamic_CreatedHour__c<8 || Dynamic_CreatedHour__c>=20, 0, Minute(TimeValue(Dynamic_Time_Start_Date_Time__c))/60)
    ),

    if( Weekday(DateValue(Dynamic_Time_Start_Date_Time__c))=7 || Weekday(DateValue(Dynamic_Time_Start_Date_Time__c))=0 || Dynamic_CreatedHour__c>=20, 0,

        /* If before 8am, assume full 12 hour day (20-8). If after, calc remaining. */
        if(Dynamic_CreatedHour__c<8, 12, 
            (20 - Dynamic_CreatedHour__c)
        )
        - 
        if(Dynamic_CreatedHour__c<8 || Dynamic_CreatedHour__c>=20, 0, (Minute(TimeValue(Dynamic_Time_Start_Date_Time__c))/60))
    )
    +
    (CASE( WEEKDAY(DateValue(Dynamic_Time_Start_Date_Time__c)),
    1 , CASE( MOD( DateValue(Now())-DateValue(Dynamic_Time_Start_Date_Time__c),7),1,0,2,1,3,2,4,3,5,4,6,5,0),
    2 , CASE( MOD( DateValue(Now())-DateValue(Dynamic_Time_Start_Date_Time__c),7),1,0,2,1,3,2,4,3,5,3,6,3,0),
    3 , CASE( MOD( DateValue(Now())-DateValue(Dynamic_Time_Start_Date_Time__c),7),1,0,2,1,3,2,4,2,5,2,6,3,0),
    4 , CASE( MOD( DateValue(Now())-DateValue(Dynamic_Time_Start_Date_Time__c),7),1,0,2,1,3,1,4,1,5,2,6,3,0),
    5 , CASE( MOD( DateValue(Now())-DateValue(Dynamic_Time_Start_Date_Time__c),7),1,0,2,0,3,0,4,1,5,2,6,2,0),
    6 , CASE( MOD( DateValue(Now())-DateValue(Dynamic_Time_Start_Date_Time__c),7),1,0,2,0,3,0,4,1,5,2,6,3,0),
    7 , CASE( MOD( DateValue(Now())-DateValue(Dynamic_Time_Start_Date_Time__c),7),1,0,2,0,3,0,4,1,5,2,6,2,0),
    999)
    +
    (FLOOR(( DateValue(Now()) - DateValue(Dynamic_Time_Start_Date_Time__c) )/7)*5))*8
    +
    /* If before 8am, 0 hours. If after 8pm, 12 hours. Else calc duration from 8am. */
    if(Dynamic_Time_End_Hour__c<8, 0, 
        if(Dynamic_Time_End_Hour__c>20, 12, Dynamic_Time_End_Hour__c-8)
    )+
    if(Dynamic_Time_End_Hour__c<8 || Dynamic_Time_End_Hour__c>=20, 0, (Minute(TimeValue(Now()))/60))

)
)
